{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "operation": "add",
    "name": "Earnings Prep Data",
    "url": "http://localhost:7805",
    "widgets_json": {
      "estimate_revisions": {
        "name": "Estimate Revisions",
        "description": "Street estimate revisions by quarter.",
        "endpoint": "/estimate-revisions",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "params": [
          {
            "paramName": "symbol",
            "type": "endpoint",
            "label": "Symbol",
            "optionsEndpoint": "/symbols",
            "value": "AAPL"
          }
        ],
        "data": {
          "table": {
            "columnsDefs": [
              {
                "field": "quarter",
                "headerName": "Quarter",
                "cellDataType": "text"
              },
              {
                "field": "eps_estimate",
                "headerName": "EPS Est",
                "cellDataType": "number"
              },
              {
                "field": "revenue_estimate_b",
                "headerName": "Revenue Est ($B)",
                "cellDataType": "number"
              }
            ]
          }
        }
      }
    },
    "apps_json": [
      {
        "name": "Revision Group App",
        "description": "Grouped revisions by symbol.",
        "tabs": {
          "revisions": {
            "id": "revisions",
            "name": "Revisions",
            "layout": [
              {
                "i": "estimate_revisions",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          }
        },
        "groups": [
          {
            "name": "Revision Symbol Group",
            "type": "param",
            "paramName": "symbol",
            "widgetIds": [
              "estimate_revisions"
            ]
          }
        ]
      }
    ]
  }
}
